// Railway Infrastructure as Code for the `prettier-config` service (replaces
// railway.toml, which Railway stops reading on 2026-12-01). Generated by
// `railway config migrate`. Restart stays Railway's default (ON_FAILURE, 10
// retries): Railway stores defaults as null, so declaring them never settles.
// Preview with `railway config plan`; nothing here runs during deploys.
import { defineRailway, github, project, service } from 'railway/iac';

// Other services in the project (fahji, MongoDB) are not owned by this file,
// so `apply` leaves them alone.
// See https://docs.railway.com/infrastructure-as-code#multi-repo-projects
export const partial = 'prettier-config';

export default defineRailway(() => {
	const prettierConfig = service('prettier-config', {
		source: github('nooobtimex/prettier-config', { branch: 'main', checkSuites: false }),
		build: { buildEnvironment: 'V3', builder: 'DOCKERFILE', dockerfilePath: 'Dockerfile' },
		start: 'node server.js',
		replicas: { 'asia-southeast1-eqsg3a': 1 },
		domains: [
			{ domain: 'prettier-config.dev', port: 2000 },
			{ domain: 'prettier-config.nooobtimex.me', port: 2000 },
		],
	});

	return project('NooobtimeX', {
		// Variables stay Railway-only, so `apply` never deletes PORT.
		variables: { managed: false },
		resources: [prettierConfig],
	});
});
